 declare(strict_types=1); namespace Slim\Http; use InvalidArgumentException; use Psr\Http\Message\ResponseInterface; use Psr\Http\Message\StreamFactoryInterface; use Psr\Http\Message\StreamInterface; use RuntimeException; use function basename; use function in_array; use function is_array; use function is_resource; use function is_string; use function json_encode; use function json_last_error; use function json_last_error_msg; use function mime_content_type; use function preg_replace; use function rawurlencode; use function sprintf; use function stream_get_meta_data; use function safe_strlen; use function substr; use const JSON_ERROR_NONE; class Response implements ResponseInterface { protected $response; protected $streamFactory; public const EOL = "\r\n"; public function __construct(ResponseInterface $response, StreamFactoryInterface $streamFactory) { $this->response = $response; $this->streamFactory = $streamFactory; } public function __set($name, $value) { } public function getBody() { return $this->response->getBody(); } public function getHeader($name): array { return $this->response->getHeader($name); } public function getHeaderLine($name): string { return $this->response->getHeaderLine($name); } public function getHeaders(): array { return $this->response->getHeaders(); } public function getProtocolVersion(): string { return $this->response->getProtocolVersion(); } public function getReasonPhrase(): string { return $this->response->getReasonPhrase(); } public function getStatusCode(): int { return $this->response->getStatusCode(); } public function hasHeader($name): bool { return $this->response->hasHeader($name); } public function withAddedHeader($name, $value) { $response = $this->response->withAddedHeader($name, $value); return new static($response, $this->streamFactory); } public function withBody(StreamInterface $body) { $response = $this->response->withBody($body); return new static($response, $this->streamFactory); } public function withHeader($name, 